SELECT 
FROM approval_task


        AND id = #{query.id}


        AND instance_id = #{query.instanceId}


        AND stage_id = #{query.stageId}


        AND approver_id = #{query.approverId}


        AND status = #{query.status}


        AND is_first_approver = #{query.isFirstApprover}


        AND task_type = #{query.taskType}


        AND sub_workflow_approver_ids IS NOT NULL


        AND status IN

            #{status}



        AND id != #{query.idNotEqual}



        AND instance_id IN (
            SELECT id FROM approval_instance WHERE business_type = #{query.businessType}
        )


ORDER BY create_time DESC

SELECT ai.id, ai.status, ai.business_type, ai.business_id, ai.create_time, ai.applicant_id, ai.workflow_id, w.name AS workflow_name, u.real_name AS applicant_name, CASE WHEN at.id IS NOT NULL THEN 'approver' ELSE 'initiator' END AS my_role, -- 业务类型相关字段 ma.id AS application_id, ma.title AS application_title, da.id AS deletion_application_id, da.title AS deletion_title, ua.id AS usage_application_id, ua.title AS usage_title FROM approval_instance ai INNER JOIN sys_user u ON ai.applicant_id = u.id INNER JOIN workflow w ON ai.workflow_id = w.id LEFT JOIN approval_task at ON at.instance_id = ai.id AND at.approver_id = #{userId} LEFT JOIN material_application ma ON ai.business_type = 'MATERIAL_ENTRY' AND ai.business_id = ma.id LEFT JOIN asset_deletion_application da ON ai.business_type = 'ASSET_DELETION' AND ai.business_id = da.id LEFT JOIN usage_apply ua ON ai.business_type = 'ASSET_USAGE' AND ai.business_id = ua.id
ai.parent_instance_id IS NULL AND (ai.applicant_id = #{userId} OR at.id IS NOT NULL)
AND ai.business_type = #{businessType}
AND ai.status = #{status}
ORDER BY ai.create_time DESC

SELECT COUNT(*)
FROM approval_task t
INNER JOIN approval_instance i ON t.instance_id = i.id

    t.approver_id = #{userId}
    AND t.status = 'PENDING'

        AND i.business_type = #{businessType}
